function f(n) {
  arguments[0] = 2;
  return n;
}
console.log(f(1));

function f(n) {
  'use strict';
  arguments[0] = 2;
  return n;
}
console.log(f(1));

function f(n = 1) {
  arguments[0] = 2;
  return n;
}
console.log(f(1));

function f() {
  const g = () => arguments[0];
  return g(2);
}
console.log(f(1));

function f() {
  var n = 0;
  eval('var n = 1');
  return n;
}
console.log(f());

function f() {
  var n = 0;
  const run = eval;
  run('var n = 1');
  console.log(n);
  console.log(globalThis.n);
}
f();

function f() {
  'use strict';
  var n = 0;
  eval('var n = 1');
  return n;
}
console.log(f());

function f() {
  let n = 1;
  const g = new Function('return typeof n === "undefined" ? 0 : 1');
  return g();
}
console.log(f());
